def flip_and_invert_image(image):
    result = []
    for row in image:
        reversed_row = row[::-1]                                           # first pass: reverse the row completely
        inverted_row = [1 - v for v in reversed_row]                       # second pass: invert every value
        result.append(inverted_row)
    return result


if __name__ == "__main__":
    print(flip_and_invert_image([[1, 1, 0], [1, 0, 1], [0, 0, 0]]))

