import java.util.*;

public class Main {
    int[][] flipAndInvertImage(int[][] image) {
        int n = image.length;
        int m = image[0].length;
        int[][] result = new int[n][m];
        for (int i = 0; i < n; i++) {
            int[] reversedRow = new int[m];
            for (int j = 0; j < m; j++) {
                reversedRow[j] = image[i][m - 1 - j];                             // first pass: reverse the row completely
            }
            for (int j = 0; j < m; j++) {
                result[i][j] = 1 - reversedRow[j];                                 // second pass: invert every value
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[][] result = solution.flipAndInvertImage(new int[][]{{1, 1, 0}, {1, 0, 1}, {0, 0, 0}});
        for (int[] row : result) System.out.println(Arrays.toString(row));
    }
}

