def flip_and_invert_image(image):
    for row in image:
        left, right = 0, len(row) - 1
        while left < right:
            row[left], row[right] = 1 - row[right], 1 - row[left]          # swap the symmetric pair AND invert both, in one combined step
            left += 1
            right -= 1
        if left == right:
            row[left] = 1 - row[left]                                     # a lone middle element (odd length) just needs inverting
    return image


if __name__ == "__main__":
