import java.util.*;

public class Main {
    int[][] flipAndInvertImage(int[][] image) {
        for (int[] row : image) {
            int left = 0, right = row.length - 1;
            while (left < right) {
                int temp = 1 - row[left];
                row[left] = 1 - row[right];                                       // swap the symmetric pair AND invert both, in one combined step
                row[right] = temp;
                left++;
                right--;
            }
            if (left == right) {
                row[left] = 1 - row[left];                                          // a lone middle element (odd length) just needs inverting
            }
        }
        return image;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[][] result = solution.flipAndInvertImage(new int[][]{{1, 1, 0}, {1, 0, 1}, {0, 0, 0}});
        for (int[] row : result) System.out.println(Arrays.toString(row));
    }
}

